# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe PaymentProviders::RazorpayPaymentLinkService do
  # A link created at the provider but never stored could be paid by a customer and never recorded, so the refusal must come before creation.
  it "refuses during a handoff before creating any Razorpay link and leaves payment_infos unchanged" do
    company = create(:india_company, base_currency: "INR")
    client = create(:client, company:, currency: "INR", phone: "+919876500022")
    invoice = create(:invoice, company:, client:, currency: "INR", amount: 1200, amount_due: 1200)
    provider = create(:payments_provider, company:, name: PaymentsProvider::RAZORPAY_PROVIDER, enabled: true, connected: true,
      accepted_payment_methods: ["razorpay"], settings: { key_id: "rzp_test_123", key_secret: "secret" })
    client_double = instance_double(PaymentProviders::RazorpayClient)
    allow(PaymentProviders::RazorpayClient).to receive(:new).and_return(client_double)
    allow(client_double).to receive(:create_payment_link)
    infos_before = invoice.reload.payment_infos
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "settle")

    service = described_class.new(invoice:, provider:, callback_url: "https://example.test/cb", notify_sms: true)

    expect { service.process }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)
    expect(client_double).not_to have_received(:create_payment_link)
    expect(invoice.reload.payment_infos).to eq(infos_before)
  end
end
